# --- PATCH 2026-10-02 : classes spectrales manquantes ---
import logging as _log
from typing import Optional as _Opt
_logger = _log.getLogger(__name__)


class AntiHallucinationValidator:
    """Validateur anti-hallucination pour sorties LLM. Utilise par SilentAuditLoop."""

    def __init__(self, threshold: float = 0.85, strict_mode: bool = False):
        self.threshold = threshold
        self.strict_mode = strict_mode
        self._history: list = []
        _logger.debug('AntiHallucinationValidator init seuil=%.2f strict=%s', threshold, strict_mode)

    def validate(self, response: str, context: str = '', source_facts: _Opt[list] = None) -> dict:
        if source_facts is None:
            source_facts = []
        if not response or not response.strip():
            r = {'valid': False, 'score': 0.0, 'issues': ['Reponse vide'], 'threshold': self.threshold}
            self._history.append(r)
            return r
        issues: list = []
        score: float = 1.0
        if context:
            cw = set(context.lower().split())
            rw = set(response.lower().split())
            if len(cw) > 20 and len(cw & rw) / len(cw) < 0.08:
                issues.append('Faible chevauchement lexical')
                score -= 0.25
        for fact in source_facts:
            if str(fact).lower() not in response.lower():
                score -= 0.10 / max(len(source_facts), 1)
        score = round(max(0.0, min(1.0, score)), 4)
        valid = (score >= self.threshold) and (not self.strict_mode or not issues)
        r = {'valid': valid, 'score': score, 'issues': issues, 'threshold': self.threshold}
        self._history.append(r)
        return r

    def check(self, text: str) -> bool:
        return self.validate(text)['valid']

    def get_history(self) -> list:
        return list(self._history)

    def reset(self) -> None:
        self._history.clear()


class SpectralMethodCore:
    """Noyau de methodes spectrales. Reference par le patcheur de demarrage Gabriel."""

    def __init__(self, mode: str = 'standard', config: _Opt[dict] = None):
        self.mode = mode
        self.config = config or {}
        self.validator = AntiHallucinationValidator(
            threshold=self.config.get('hallucination_threshold', 0.85),
            strict_mode=self.config.get('strict_mode', False),
        )
        self._initialized = True
        _logger.info('SpectralMethodCore init mode=%s', self.mode)

    def process(self, data: dict) -> dict:
        if not data:
            return {'status': 'error', 'message': 'Donnees vides', 'mode': self.mode}
        return {'status': 'ok', 'mode': self.mode, 'processed': True, 'data': data}

    def analyze(self, text: str, context: str = '') -> dict:
        v = self.validator.validate(text, context)
        tl = text.lower()
        signals = (["error_signal"] if "erreur" in tl or "error" in tl else []) + \
                  (["question_signal"] if "?" in text else []) + \
                  (["long_output_signal"] if len(text) > 1000 else [])
        return {'text_length': len(text), 'validation': v, 'mode': self.mode, 'signals': signals}

    @property
    def is_initialized(self) -> bool:
        return self._initialized
